#region "FormPlugin"
public class FormPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaFormPlugin
{
	ContextMenuStrip myTemplateProfileContextMenuStrip;
	
    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void SetupBeforeHandlers(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm JiwaForm, JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		var staffForm = (JiwaFinancials.Jiwa.JiwaStaffUI.frmMain) JiwaForm;
		myTemplateProfileContextMenuStrip = new ContextMenuStrip();
		var newToolStripMenuItem = new ToolStripMenuItem("Clear", null, ClearTemplateProfile, "Clear");
		myTemplateProfileContextMenuStrip.Items.Add(newToolStripMenuItem);	
		staffForm.grdCustomFields.CellClick += grdCustomFields_CellClick;
    }

	private void grdCustomFields_CellClick(System.Object sender, FarPoint.Win.Spread.CellClickEventArgs e)
	{
		if (e.ColumnHeader == false && e.Button == MouseButtons.Right) 
		{
			var hostGrid = (JiwaFinancials.Jiwa.JiwaApplication.Controls.JiwaGrid) sender;	
			hostGrid.ActiveSheet.SetActiveCell(e.Row,e.Column);
			if (e.Column == hostGrid.ActiveSheet.Columns["Contents"].Index && hostGrid.get_GridText("SettingName", e.Row).ToString() == "TemplateProfile")
				myTemplateProfileContextMenuStrip.Show(hostGrid, e.X, e.Y);					
		}
	}	
		
	private void ClearTemplateProfile(System.Object sender, System.EventArgs e)
	{
		var toolStripItem = (System.Windows.Forms.ToolStripItem) sender;
		var contextMenuStrip = (System.Windows.Forms.ContextMenuStrip) toolStripItem.Owner;
		var hostGrid = (JiwaFinancials.Jiwa.JiwaApplication.Controls.JiwaGrid) contextMenuStrip.SourceControl;
		var staffForm = (JiwaFinancials.Jiwa.JiwaStaffUI.frmMain) JiwaFinancials.Jiwa.JiwaApplication.Manager.GetOwnerForm(hostGrid);
		foreach(JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomFieldValue customFieldValue in staffForm.Staff.CustomFieldValues) 
		{
			if (customFieldValue.CustomField.PluginCustomField.Name == "TemplateProfile")
			{
				customFieldValue.Contents = "";
				customFieldValue.DisplayContents = "";
				customFieldValue.NotifyPropertyChanged("Contents");
				break;
			}
		}
	}	
}
#endregion

