#region "ApplicationManagerPlugin"
public class ApplicationManagerPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaApplicationManagerPlugin
{
	private JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin _plugin;

    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void Setup(JiwaFinancials.Jiwa.JiwaApplication.Plugin.Plugin Plugin)
    {
		_plugin = Plugin;
		Plugin.Manager.LoggedOn += delegate() { LoggedOn(Plugin.Manager); };
    }
	
	public void LoggedOn(JiwaFinancials.Jiwa.JiwaApplication.Manager Manager)
	{
		// read model userid from system settings
		string modelUserID = Manager.Database.ReadSysData(_plugin.Name, "TemplateProfile", "").ToString();
		foreach(JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomFieldValue customFieldValue in Manager.Staff.CustomFieldValues) 
		{
			if (customFieldValue.CustomField.PluginCustomField.Name == "TemplateProfile")
			{
				modelUserID = customFieldValue.Contents;
				break;
			}
		}		
		string Sql;
		
		if (modelUserID.Trim().Length > 0 && modelUserID != Manager.Staff.RecID)
		{
			Manager.Database.UserSettings.Clear();
			
			// Copy from model user
			
	        SqlDataReader SQLReader = null;
	        SqlParameter SQLParam = null;

			var db = Manager.Database;
			
	        try {				
				
				// Read user profile settings
	            Sql = @"SELECT Section, IDKey, Contents
	                			FROM SY_UserProfile
	                			WHERE UserID = @ModelUserID
	                			ORDER BY Section, IDKey";

	            using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction))
				{
	                SQLParam = new SqlParameter("@ModelUserID", System.Data.SqlDbType.Char);
	                SQLParam.Value = modelUserID;
	                SQLCmd.Parameters.Add(SQLParam);

	                SQLReader = db.ExecuteReader(SQLCmd);

	                while (SQLReader.Read() == true) 
					{
	                    var newUserSetting = new JiwaFinancials.Jiwa.JiwaODBC.clsUserSetting();
	                    newUserSetting.Section = db.Sanitise(SQLReader, "Section").ToString();
	                    newUserSetting.IDKey = db.Sanitise(SQLReader, "IDKey").ToString();
	                    newUserSetting.Contents = db.Sanitise(SQLReader, "Contents").ToString();
	                    db.UserSettings.Add(newUserSetting);
	                }

	                SQLReader.Close();
	            }
	        } finally 
			{
	            if (SQLReader != null)
				{
	                SQLReader.Close();
				}	
			}
			
			// Delete SY_TabControlSettings (Deletion of SY_TabControlSettings will cascade to SY_TabSettings)
			Sql = @"DELETE FROM SY_TabControlSettings WHERE HR_Staff_RecID = @CurrentUserID";

            using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction))
			{
                SQLParam = new SqlParameter("@CurrentUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = Manager.Staff.RecID;
                SQLCmd.Parameters.Add(SQLParam);

                db.ExecuteNonQuery(SQLCmd);
            }
			
			// Insert SY_TabControlSettings
			Sql = @"INSERT INTO SY_TabControlSettings (RecID, HR_Staff_RecID, Context, FullName, UseCustomTabs, TabOrderXML)  
					SELECT LEFT(REPLACE(NEWID(), '-', ''), 20), @CurrentUserID, Context, FullName, UseCustomTabs, TabOrderXML
					FROM SY_TabControlSettings					
					WHERE SY_TabControlSettings.HR_Staff_RecID = @ModelUserID";

            using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction))
			{
                SQLParam = new SqlParameter("@CurrentUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = Manager.Staff.RecID;
                SQLCmd.Parameters.Add(SQLParam);

				SQLParam = new SqlParameter("@ModelUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = modelUserID;
                SQLCmd.Parameters.Add(SQLParam);
				
                db.ExecuteNonQuery(SQLCmd);
            }
			
			// Insert SY_TabSettings
			Sql = @"INSERT INTO SY_TabSettings(RecID, SY_TabControlSettings_RecID, TabKey, Text, Visible)
					SELECT LEFT(REPLACE(NEWID(), '-', ''), 20), 
					(SELECT TOP 1 RecID FROM SY_TabControlSettings WHERE SY_TabControlSettings.HR_Staff_RecID = @CurrentUserID AND SY_TabControlSettings.FullName = Model_SY_TabControlSettings.FullName AND SY_TabControlSettings.Context = Model_SY_TabControlSettings.Context), 
					Model_SY_TabSettings.TabKey, Model_SY_TabSettings.Text, Model_SY_TabSettings.Visible 
					FROM SY_TabSettings	Model_SY_TabSettings
					JOIN SY_TabControlSettings Model_SY_TabControlSettings ON Model_SY_TabControlSettings.RecID = Model_SY_TabSettings.SY_TabControlSettings_RecID
					WHERE Model_SY_TabControlSettings.HR_Staff_RecID = @ModelUserID";

            using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction))
			{                
				SQLParam = new SqlParameter("@ModelUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = modelUserID;
                SQLCmd.Parameters.Add(SQLParam);
				
				SQLParam = new SqlParameter("@CurrentUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = Manager.Staff.RecID;
                SQLCmd.Parameters.Add(SQLParam);
				
                db.ExecuteNonQuery(SQLCmd);
            }
			
			//SY_FormSettings
			// Delete SY_FormSettings 
			Sql = @"DELETE FROM SY_FormSettings WHERE HR_Staff_RecID = @CurrentUserID";

            using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction))
			{
                SQLParam = new SqlParameter("@CurrentUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = Manager.Staff.RecID;
                SQLCmd.Parameters.Add(SQLParam);

                db.ExecuteNonQuery(SQLCmd);
            }
			
			// Insert SY_FormSettings
			Sql = @"INSERT INTO SY_FormSettings (RecID, SY_Forms_ClassName, HR_Staff_RecID, WindowState, [Top], [Left], Width, Height, Context, Floating)  
					SELECT NEWID(), SY_Forms_ClassName, @CurrentUserID, WindowState, [Top], [Left], Width, Height, Context, Floating 
					FROM SY_FormSettings					
					WHERE SY_FormSettings.HR_Staff_RecID = @ModelUserID";

            using (SqlCommand SQLCmd = new SqlCommand(Sql, db.SQLConnection, db.SQLTransaction))
			{
                SQLParam = new SqlParameter("@CurrentUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = Manager.Staff.RecID;
                SQLCmd.Parameters.Add(SQLParam);

				SQLParam = new SqlParameter("@ModelUserID", System.Data.SqlDbType.Char);
                SQLParam.Value = modelUserID;
                SQLCmd.Parameters.Add(SQLParam);
				
                db.ExecuteNonQuery(SQLCmd);
            }			
		}
	}
}
#endregion

#region "CustomFieldPlugin"
public class CustomFieldPlugin : System.MarshalByRefObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaCustomFieldPlugin
{
    public override object InitializeLifetimeService()
    {
        // returning null here will prevent the lease manager
        // from deleting the Object.
        return null;
    }

    public void FormatCell(JiwaFinancials.Jiwa.JiwaApplication.IJiwaBusinessLogic BusinessLogicHost, JiwaFinancials.Jiwa.JiwaApplication.Controls.JiwaGrid GridObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm FormObject, int Col, int Row, JiwaFinancials.Jiwa.JiwaApplication.IJiwaCustomFieldValues HostObject, JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomField CustomField, JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomFieldValue CustomFieldValue)
    {
    }

    public void ReadData(JiwaFinancials.Jiwa.JiwaApplication.IJiwaBusinessLogic BusinessLogicHost, JiwaFinancials.Jiwa.JiwaApplication.Controls.JiwaGrid GridObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm FormObject, int Row, JiwaFinancials.Jiwa.JiwaApplication.IJiwaCustomFieldValues HostObject, JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomField CustomField, JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomFieldValue CustomFieldValue)
    {		
		if (CustomField.PluginCustomField.Name == "TemplateProfile") 
		{
			if (CustomFieldValue.Contents.Trim().Length > 0) {
				var staff = CustomField.Manager.EntityFactory.CreateEntity<JiwaFinancials.Jiwa.JiwaApplication.Entities.Staff.Staff>();
				try
				{
				staff.ReadRecord(CustomFieldValue.Contents);
				CustomFieldValue.DisplayContents = String.Format("{0}", staff.DisplayName);						
				}
				catch(JiwaFinancials.Jiwa.JiwaApplication.Exceptions.RecordNotFoundException ex)
				{
					CustomFieldValue.DisplayContents = "";
				}
			}
		}		
    }

    public void ButtonClicked(JiwaFinancials.Jiwa.JiwaApplication.IJiwaBusinessLogic BusinessLogicHost, JiwaFinancials.Jiwa.JiwaApplication.Controls.JiwaGrid GridObject, JiwaFinancials.Jiwa.JiwaApplication.IJiwaForm FormObject, int Col, int Row, JiwaFinancials.Jiwa.JiwaApplication.IJiwaCustomFieldValues HostObject, JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomField CustomField, JiwaFinancials.Jiwa.JiwaApplication.CustomFields.CustomFieldValue CustomFieldValue)
    {
		if (CustomField.PluginCustomField.Name == "TemplateProfile") 
		{
			var staff = CustomField.Manager.EntityFactory.CreateEntity<JiwaFinancials.Jiwa.JiwaApplication.Entities.Staff.Staff>();
			staff.Search(FormObject.Form);
			if(staff != null && staff.RecID != null && staff.RecID.Trim().Length >0)
			{
				CustomFieldValue.Contents = staff.RecID;
				CustomFieldValue.DisplayContents = String.Format("{0}", staff.DisplayName);						
			}
		}		
    }
}
#endregion

